// Airship Pet — a pixel-art airship that drifts across the desktop sky.
// Sprites are generated by tools/gen_airship.py (64x41 px, scaled x3).
// Built after fox-pet@local: same sprite/frame approach, tick loop and menu.

import GLib from 'gi://GLib';
import Gio from 'gi://Gio';
import St from 'gi://St';
import Clutter from 'gi://Clutter';

import * as Main from 'resource:///org/gnome/shell/ui/main.js';
import * as PanelMenu from 'resource:///org/gnome/shell/ui/panelMenu.js';
import * as PopupMenu from 'resource:///org/gnome/shell/ui/popupMenu.js';
import {Extension} from 'resource:///org/gnome/shell/extensions/extension.js';

const SPRITE_W = 192;
const SPRITE_H = 123;
const TICK_MS = 50;

// name -> number of frames
const ANIMS = {fly: 4, turn: 2, puff: 5};

const PUFF_TICKS = 25; // 5 frames x 5 ticks
const TURN_TICKS = 8;

const DEFAULTS = {visible: true, follow: false, aboveWindows: true};

const rand = (a, b) => a + Math.random() * (b - a);
const randi = (a, b) => Math.floor(rand(a, b + 1));
const chance = p => Math.random() < p;
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

function pickWeighted(table) {
    const total = table.reduce((s, [, w]) => s + w, 0);
    let r = Math.random() * total;
    for (const [v, w] of table) {
        r -= w;
        if (r <= 0)
            return v;
    }
    return table[table.length - 1][0];
}

class Airship {
    constructor(dir) {
        this._sf = St.ThemeContext.get_for_stage(global.stage).scale_factor;
        this.w = SPRITE_W * this._sf;
        this.h = SPRITE_H * this._sf;

        this.actor = new St.Widget({
            reactive: false,
            width: this.w,
            height: this.h,
        });

        // One pre-built child per frame; we only toggle visibility.
        this._frames = {};
        for (const [name, n] of Object.entries(ANIMS)) {
            for (let i = 0; i < n; i++) {
                for (const d of ['r', 'l']) {
                    const path = GLib.build_filenamev([dir, 'sprites', `${name}_${i}_${d}.png`]);
                    const w = new St.Widget({
                        reactive: false,
                        visible: false,
                        style: `background-image: url("${path}"); width: ${SPRITE_W}px; height: ${SPRITE_H}px;`,
                    });
                    this.actor.add_child(w);
                    this._frames[`${name}_${i}_${d}`] = w;
                }
            }
        }

        // Hitbox around the envelope + gondola (not the empty headroom).
        this._hit = new St.Widget({
            reactive: true,
            track_hover: true,
            x: Math.round(this.w * 0.04),
            y: Math.round(this.h * 0.2),
            width: Math.round(this.w * 0.88),
            height: Math.round(this.h * 0.75),
        });
        this.actor.add_child(this._hit);
        this._hit.connect('button-press-event', (_a, e) => this._onPress(e));
        this._hit.connect('motion-event', (_a, e) => this._onMotion(e));
        this._hit.connect('button-release-event', (_a, e) => this._onRelease(e));

        this._shown = null;
        this.dead = false;
        this.actor.connect('destroy', () => {
            this.dead = true;
            this._endGrab();
        });

        const prim = Main.layoutManager.primaryMonitor;
        this.dir = 'r';
        this.x = prim.x + this.w;
        this.y = this._skyBand(this.x)[0] + this.h * 0.3;
        this.vx = 0;
        this.vy = 0;
        this.dragging = false;
        this.follow = false;
        this.puffT = 0;
        this._bob = 0;
        this._prop = 0;
        this._followPause = 0;

        this._cruiseTo(prim.x + prim.width * rand(0.3, 0.7), this.y, false);
    }

    // ---------------------------------------------------------- geometry

    _boundsX() {
        const ms = Main.layoutManager.monitors;
        const minX = Math.min(...ms.map(m => m.x));
        const maxX = Math.max(...ms.map(m => m.x + m.width));
        return [minX + this.w / 2, maxX - this.w / 2];
    }

    _monitorAt(x) {
        const ms = Main.layoutManager.monitors;
        const i = ms.findIndex(m => x >= m.x && x < m.x + m.width);
        return i >= 0 ? i : Main.layoutManager.primaryIndex;
    }

    monitorIndex() {
        return this._monitorAt(this.x);
    }

    // Vertical limits for the ship centre on the monitor under x.
    _boundsY(x) {
        const wa = Main.layoutManager.getWorkAreaForMonitor(this._monitorAt(x));
        return [wa.y + this.h * 0.4, wa.y + wa.height - this.h * 0.5];
    }

    // Preferred cruising altitudes: upper part of the screen.
    _skyBand(x) {
        const wa = Main.layoutManager.getWorkAreaForMonitor(this._monitorAt(x));
        const lo = wa.y + this.h * 0.5;
        return [lo, Math.max(lo, wa.y + wa.height * 0.4)];
    }

    // ---------------------------------------------------------- dragging

    _onPress(e) {
        if (e.get_button() !== 1)
            return Clutter.EVENT_PROPAGATE;
        const [ex, ey] = e.get_coords();
        this._drag = {sx: ex, sy: ey, offX: ex - this.x, offY: ey - this.y, moved: false,
            hist: [[ex, ey, GLib.get_monotonic_time()]]};
        this._grab = global.stage.grab(this._hit);
        return Clutter.EVENT_STOP;
    }

    _onMotion(e) {
        if (!this._drag)
            return Clutter.EVENT_PROPAGATE;
        const [ex, ey] = e.get_coords();
        const d = this._drag;
        if (!d.moved && Math.hypot(ex - d.sx, ey - d.sy) > 6 * this._sf) {
            d.moved = true;
            this.dragging = true;
            this._setState('drift', 0);
        }
        if (d.moved) {
            this.x = ex - d.offX;
            this.y = ey - d.offY;
            d.hist.push([ex, ey, GLib.get_monotonic_time()]);
            if (d.hist.length > 8)
                d.hist.shift();
            this._render();
        }
        return Clutter.EVENT_STOP;
    }

    _onRelease(e) {
        if (!this._drag)
            return Clutter.EVENT_PROPAGATE;
        const d = this._drag;
        this._drag = null;
        this._endGrab();
        if (!d.moved) {
            // simple click: blow the whistle
            this.honk();
            return Clutter.EVENT_STOP;
        }
        this.dragging = false;
        // throw velocity from the last ~120 ms of pointer motion
        const now = GLib.get_monotonic_time();
        const recent = d.hist.filter(h => now - h[2] < 120000);
        let vx = 0, vy = 0;
        if (recent.length >= 2) {
            const a = recent[0], b = recent[recent.length - 1];
            const dt = Math.max(1, (b[2] - a[2]) / 1000) / TICK_MS;
            const lim = 30 * this._sf;
            vx = clamp((b[0] - a[0]) / dt, -lim, lim);
            vy = clamp((b[1] - a[1]) / dt, -lim, lim);
        }
        this.vx = vx;
        this.vy = vy;
        this._followPause = 600; // stay roughly where it was put for ~30 s
        this._setState('drift', 0);
        return Clutter.EVENT_STOP;
    }

    _endGrab() {
        this._grab?.dismiss();
        this._grab = null;
    }

    // ---------------------------------------------------------- states

    _setState(state, ticks, opts = {}) {
        this.state = state;
        this.ticks = ticks;
        this.age = 0;
        if ('tx' in opts) {
            this.tx = opts.tx;
            this.ty = opts.ty;
            this.fast = opts.fast ?? false;
        }
    }

    _cruiseTo(x, y, fast) {
        const [lo, hi] = this._boundsX();
        x = clamp(x, lo, hi);
        const [ylo, yhi] = this._boundsY(x);
        y = clamp(y, ylo, yhi);
        if (Math.hypot(x - this.x, y - this.y) < 10 * this._sf) {
            this._setState('hover', randi(60, 160));
            return;
        }
        this._setState('cruise', 0, {tx: x, ty: y, fast});
    }

    _turn() {
        this._setState('turn', TURN_TICKS);
    }

    _chooseNext() {
        const [lo, hi] = this._boundsX();
        const next = pickWeighted([['cruise', 40], ['short', 15], ['hover', 30], ['puff', 10], ['cursor', 5]]);
        switch (next) {
        case 'cruise': {
            const x = rand(lo, hi);
            const [a, b] = this._skyBand(x);
            this._cruiseTo(x, rand(a, b), false);
            break;
        }
        case 'short': {
            const x = this.x + (chance(0.5) ? 1 : -1) * rand(150, 400) * this._sf;
            const [a, b] = this._skyBand(x);
            this._cruiseTo(x, clamp(this.y + rand(-60, 60) * this._sf, a, b), false);
            break;
        }
        case 'puff':
            this.honk();
            this._setState('hover', randi(40, 100));
            break;
        case 'cursor':
            this.call();
            break;
        default:
            this._setState('hover', randi(60, 240));
        }
    }

    honk() {
        if (this.puffT <= 0)
            this.puffT = PUFF_TICKS;
    }

    call() {
        if (this.dragging)
            return;
        const [px, py] = global.get_pointer();
        const side = px >= this.x ? -1 : 1;
        this._cruiseTo(px + side * this.w * 0.6, py - this.h * 0.8,
            Math.abs(px - this.x) > 300 * this._sf);
    }

    // Fly to the far side of the screen.
    voyage() {
        if (this.dragging)
            return;
        const [lo, hi] = this._boundsX();
        const x = this.x - lo > hi - this.x ? lo : hi;
        const [a, b] = this._skyBand(x);
        this._cruiseTo(x, rand(a, b), true);
    }

    // ---------------------------------------------------------- tick

    tick() {
        this.age++;
        this._bob += 0.06;
        if (this.puffT > 0)
            this.puffT--;
        if (this.dragging) {
            this._prop += 0.6;
            this._render();
            return;
        }
        if (this._followPause > 0)
            this._followPause--;

        const [px, py] = global.get_pointer();

        // Follow-cursor mode: keep station beside and above the pointer.
        if (this.follow && this._followPause === 0 && !['turn', 'drift'].includes(this.state)) {
            const side = px >= this.x ? -1 : 1;
            const gx = px + side * this.w * 0.6;
            const gy = py - this.h * 0.8;
            const far = 120 * this._sf;
            if (Math.hypot(gx - this.x, gy - this.y) > far) {
                if (this.state !== 'cruise' || Math.hypot(gx - this.tx, gy - this.ty) > far)
                    this._cruiseTo(gx, gy, Math.abs(gx - this.x) > 450 * this._sf);
            } else if (this.state === 'cruise') {
                this._setState('hover', randi(40, 120));
            }
        }

        switch (this.state) {
        case 'cruise': {
            const want = this.tx >= this.x ? 'r' : 'l';
            const dx = this.tx - this.x;
            const dy = this.ty - this.y;
            if (want !== this.dir && Math.abs(dx) > 24 * this._sf) {
                this._turn();
                this._resume = {tx: this.tx, ty: this.ty, fast: this.fast};
                break;
            }
            const speed = (this.fast ? 5 : 1.5) * this._sf;
            const dist = Math.hypot(dx, dy);
            if (dist < 4 * this._sf) {
                this._setState('hover', randi(60, 240));
                break;
            }
            // ease in/out: slow down near the target, steer smoothly
            const v = Math.min(speed, dist * 0.04 + 0.3 * this._sf);
            const wx = dx / dist * v;
            const wy = dy / dist * v * 0.6;
            this.vx += (wx - this.vx) * 0.06;
            this.vy += (wy - this.vy) * 0.06;
            break;
        }
        case 'turn':
            this.vx *= 0.88;
            this.vy *= 0.88;
            if (--this.ticks <= 0) {
                this.dir = this.dir === 'r' ? 'l' : 'r';
                const r = this._resume;
                this._resume = null;
                if (r)
                    this._setState('cruise', 0, r);
                else
                    this._setState('hover', randi(20, 60));
            }
            break;
        case 'drift': {
            // after a throw: coast to a stop, buoyancy pulls back into range
            this.vx *= 0.95;
            this.vy *= 0.93;
            const [ylo, yhi] = this._boundsY(this.x);
            if (this.y > yhi)
                this.vy -= 0.4 * this._sf;
            else if (this.y < ylo)
                this.vy += 0.4 * this._sf;
            if (Math.hypot(this.vx, this.vy) < 0.25 * this._sf)
                this._setState('hover', randi(60, 160));
            break;
        }
        default: // hover
            this.vx *= 0.92;
            this.vy *= 0.92;
            if (--this.ticks <= 0 && !this.follow)
                this._chooseNext();
            else if (this.follow && this.ticks <= 0)
                this.ticks = 20;
            // face the cursor while hovering in follow mode
            if (this.follow && Math.abs(px - this.x) > 40 * this._sf && (px >= this.x ? 'r' : 'l') !== this.dir)
                this._turn();
        }

        this.x += this.vx;
        this.y += this.vy;

        // keep on screen; bounce softly off the edges
        const [lo, hi] = this._boundsX();
        if (this.x < lo || this.x > hi) {
            this.x = clamp(this.x, lo, hi);
            this.vx = -this.vx * 0.4;
        }
        if (this.state !== 'drift') {
            const [ylo, yhi] = this._boundsY(this.x);
            this.y = clamp(this.y, ylo, yhi);
        }

        // propeller spins faster with speed
        this._prop += 0.3 + Math.abs(this.vx) / this._sf * 0.35;
        this._render();
    }

    _frameName() {
        if (this.state === 'turn') {
            // old side: wide -> narrow, then new side: narrow -> wide
            const k = Math.min(3, Math.floor(this.age / (TURN_TICKS / 4)));
            const other = this.dir === 'r' ? 'l' : 'r';
            return [['turn_0', this.dir], ['turn_1', this.dir], ['turn_1', other], ['turn_0', other]][k];
        }
        if (this.puffT > 0) {
            const k = Math.min(4, Math.floor((PUFF_TICKS - this.puffT) / 5));
            return [`puff_${k}`, this.dir];
        }
        return [`fly_${Math.floor(this._prop) % 4}`, this.dir];
    }

    _render() {
        const [name, d] = this._frameName();
        const key = `${name}_${d}`;
        if (key !== this._shown) {
            if (this._shown)
                this._frames[this._shown].hide();
            this._frames[key].show();
            this._shown = key;
        }
        const bob = this.dragging ? 0 : Math.sin(this._bob) * 3 * this._sf;
        this.actor.set_position(Math.round(this.x - this.w / 2), Math.round(this.y - this.h / 2 + bob));
    }

    destroy() {
        this._endGrab();
        if (!this.dead)
            this.actor.destroy();
    }
}

export default class AirshipPetExtension extends Extension {
    enable() {
        this._settingsPath = GLib.build_filenamev([GLib.get_user_config_dir(), 'airship-pet.json']);
        this._settings = {...DEFAULTS, ...this._loadSettings()};

        this._ship = new Airship(this.path);
        this._ship.follow = this._settings.follow;
        this._placeActor();

        this._buildIndicator();

        this._overviewIds = [
            Main.overview.connect('showing', () => this._updateVisibility()),
            Main.overview.connect('hidden', () => this._updateVisibility()),
        ];
        this._fsId = global.display.connect('in-fullscreen-changed', () => this._updateVisibility());
        this._monId = Main.layoutManager.connect('monitors-changed', () => this._updateVisibility());

        this._timer = GLib.timeout_add(GLib.PRIORITY_DEFAULT, TICK_MS, () => {
            if (this._ship.dead)
                return GLib.SOURCE_REMOVE;
            if (this._ship.actor.visible)
                this._ship.tick();
            return GLib.SOURCE_CONTINUE;
        });
        this._updateVisibility();
    }

    disable() {
        if (this._timer) {
            GLib.source_remove(this._timer);
            this._timer = 0;
        }
        this._overviewIds?.forEach(id => Main.overview.disconnect(id));
        this._overviewIds = null;
        if (this._fsId)
            global.display.disconnect(this._fsId);
        if (this._monId)
            Main.layoutManager.disconnect(this._monId);
        this._fsId = this._monId = 0;
        this._indicator?.destroy();
        this._indicator = null;
        this._ship?.destroy();
        this._ship = null;
    }

    // ---------------------------------------------------------- helpers

    _loadSettings() {
        try {
            const [ok, bytes] = GLib.file_get_contents(this._settingsPath);
            if (ok)
                return JSON.parse(new TextDecoder().decode(bytes));
        } catch (e) {}
        return {};
    }

    _saveSettings() {
        try {
            GLib.file_set_contents(this._settingsPath, JSON.stringify(this._settings, null, 2));
        } catch (e) {
            console.warn(`airship-pet: cannot save settings: ${e.message}`);
        }
    }

    _placeActor() {
        const actor = this._ship.actor;
        actor.get_parent()?.remove_child(actor);
        if (this._settings.aboveWindows) {
            // Above windows, below the top panel / popups.
            Main.layoutManager.uiGroup.insert_child_below(actor, Main.layoutManager.panelBox);
        } else {
            // On the desktop: right above the wallpaper, below all windows.
            global.window_group.insert_child_above(actor, Main.layoutManager._backgroundGroup);
        }
    }

    _updateVisibility() {
        if (!this._ship)
            return;
        const mon = Main.layoutManager.monitors[this._ship.monitorIndex()];
        const fullscreen = this._settings.aboveWindows && mon?.inFullscreen;
        this._ship.actor.visible = this._settings.visible && !Main.overview.visible && !fullscreen;
    }

    _buildIndicator() {
        this._indicator = new PanelMenu.Button(0.0, 'Airship Pet', false);
        this._indicator.add_child(new St.Icon({
            gicon: Gio.FileIcon.new(Gio.File.new_for_path(GLib.build_filenamev([this.path, 'icon.png']))),
            style_class: 'system-status-icon',
        }));
        const menu = this._indicator.menu;

        const show = new PopupMenu.PopupSwitchMenuItem('Показывать дирижабль', this._settings.visible);
        show.connect('toggled', (_i, v) => {
            this._settings.visible = v;
            this._saveSettings();
            this._updateVisibility();
        });
        menu.addMenuItem(show);

        const follow = new PopupMenu.PopupSwitchMenuItem('Лететь за курсором', this._settings.follow);
        follow.connect('toggled', (_i, v) => {
            this._settings.follow = v;
            this._ship.follow = v;
            this._saveSettings();
        });
        menu.addMenuItem(follow);

        const above = new PopupMenu.PopupSwitchMenuItem('Поверх окон', this._settings.aboveWindows);
        above.connect('toggled', (_i, v) => {
            this._settings.aboveWindows = v;
            this._saveSettings();
            this._placeActor();
            this._updateVisibility();
        });
        menu.addMenuItem(above);

        menu.addMenuItem(new PopupMenu.PopupSeparatorMenuItem());

        menu.addAction('Позвать к курсору', () => this._ship.call());
        menu.addAction('Дать гудок', () => this._ship.honk());
        menu.addAction('Облететь экран', () => this._ship.voyage());

        Main.panel.addToStatusArea(this.uuid, this._indicator);
    }
}
